class NeedMore(Exception):pass
class Decoder:
    def __init__(self):self.buffer=b''
    def feed(self,chunk):
        self.buffer+=chunk;result=[]
        while self.buffer:
            try:tag,value,end=self.parse(0,0)
            except NeedMore:break
            result.append({'kind':'push' if tag==b'>' else 'reply','value':value});self.buffer=self.buffer[end:]
        return result
    def parse(self,pos,depth):
        if depth>32:raise ValueError('RESP nesting budget')
        raw=self.buffer
        if pos>=len(raw):raise NeedMore()
        tag=raw[pos:pos+1];end=raw.find(b'\r\n',pos+1)
        if end<0:raise NeedMore()
        line=raw[pos+1:end];cursor=end+2
        if tag==b'+':return tag,line,cursor
        if tag==b'-':return tag,{'error':line},cursor
        if tag==b':':return tag,int(line),cursor
        if tag==b'_':
            if line:raise ValueError('invalid null')
            return tag,None,cursor
        if tag==b'$':
            size=int(line)
            if size==-1:return tag,None,cursor
            if not 0<=size<=1048576:raise ValueError('bulk budget')
            if len(raw)<cursor+size+2:raise NeedMore()
            if raw[cursor+size:cursor+size+2]!=b'\r\n':raise ValueError('bulk delimiter')
            return tag,raw[cursor:cursor+size],cursor+size+2
        if tag in (b'*',b'%',b'>'):
            size=int(line)
            if size==-1 and tag==b'*':return tag,None,cursor
            if not 0<=size<=4096:raise ValueError('aggregate budget')
            values=[]
            for _ in range(size*(2 if tag==b'%' else 1)):
                _,value,cursor=self.parse(cursor,depth+1);values.append(value)
            return tag,dict(zip(values[::2],values[1::2])) if tag==b'%' else values,cursor
        raise ValueError('unsupported RESP tag')

    def finish(self):
        if self.buffer:raise ValueError("truncated RESP frame at EOF")
        return []

