import argparse,base64,hashlib,json,os,re,socket,sys
from pathlib import Path
import task

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


ARTIFACT_NAMES = ('request.json','wire.partial','wire.bin','frames.json','replies.json','cache.json','manifest.json','validated.json','published.json','failure.json')


def publish_bytes(path, data):
    # Publish by hard link: the final name is created atomically without replacing any winner.
    if path.is_symlink():
        raise ValueError('artifact symlink is not allowed')
    temporary = path.with_name(path.name + '.tmp-' + str(os.getpid()))
    try:
        with temporary.open('xb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path, follow_symlinks=False)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise ValueError('immutable artifact differs: ' + path.name)
    finally:
        temporary.unlink(missing_ok=True)


def write_new(path, value):
    publish_bytes(path, canonical(value) + b'\n')


def prepare_directory(root, generation):
    # A caller-supplied root alias denotes its real directory. Child aliases are never followed.
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    directory = root / generation
    if directory.is_symlink():
        raise ValueError('generation symlink is not allowed')
    directory.mkdir(exist_ok=True)
    if directory.resolve() != directory:
        raise ValueError('generation escapes root')
    for name in ARTIFACT_NAMES:
        if (directory / name).is_symlink():
            raise ValueError('artifact symlink is not allowed')
    return directory


def b64(value):return base64.b64encode(value).decode('ascii')


def binary(value):
    if not isinstance(value,str):raise ValueError('base64 string required')
    return base64.b64decode(value,validate=True)


def typed(value):
    if value is None:return {'type':'null'}
    if type(value)is int:return {'type':'integer','value':value}
    if isinstance(value,bytes):return {'type':'bytes','base64':b64(value)}
    if isinstance(value,str):return {'type':'text','value':value}
    if isinstance(value,list):return {'type':'array','items':[typed(v)for v in value]}
    if isinstance(value,dict):
        pairs=[[typed(k),typed(v)]for k,v in value.items()]
        pairs.sort(key=lambda pair:canonical(pair[0]))
        return {'type':'map','items':pairs}
    raise ValueError('unsupported decoded value')


def wire(parts):
    return ('*%d\r\n'%len(parts)).encode()+b''.join(('$%d\r\n'%len(p)).encode()+p+b'\r\n'for p in parts)


def requests(value,prefix):
    stages=value['stages']
    if not isinstance(stages,list)or not 1<=len(stages)<=8:raise ValueError('bounded stages')
    result=[]
    for stage in stages:
        if not isinstance(stage,list)or not 1<=len(stage)<=50:raise ValueError('bounded pipeline')
        batch=[]
        for command in stage:
            if not isinstance(command,list):raise ValueError('command array')
            parts=[binary(x)for x in command]
            if (not parts or parts[0]not in (b'GET',b'INCR',b'LPUSH',b'PING')or
                    (parts[0]==b'PING'and len(parts)!=1)or
                    (parts[0]in(b'GET',b'INCR')and len(parts)!=2)or
                    (parts[0]==b'LPUSH'and not 3<=len(parts)<=8)):
                raise ValueError('approved pipeline command')
            if len(parts)>1 and not parts[1].startswith(prefix.encode()):raise ValueError('key outside dedicated prefix')
            if any(len(p)>1048576 for p in parts):raise ValueError('command bulk budget')
            batch.append(parts)
        result.append(batch)
    return result


def outputs(request,frames,prefix):
    commands=[command for stage in requests(request,prefix)for command in stage]
    normals=[f['value']for f in frames if f['kind']=='reply']
    if (len(normals)!=len(commands)+3 or not isinstance(normals[0],dict)or
            normals[0].get(b'proto')!=3 or normals[0].get(b'server')!=b'redis' or
            normals[1]!=b'OK' or normals[-1]!=b'OK'):
        raise ValueError('incomplete or unaligned RESP3 session')
    cache={};replies=[];slot=-2;invalidations=[]
    for frame in frames:
        value=frame['value']
        if frame['kind']=='push':
            if not isinstance(value,list)or len(value)!=2 or value[0]!=b'invalidate':raise ValueError('unsupported native push')
            if value[1]is None:cache.clear();invalidations.append(None)
            else:
                if not isinstance(value[1],list)or any(not isinstance(k,bytes)for k in value[1]):raise ValueError('push keys')
                for key in value[1]:cache.pop(key,None);invalidations.append(b64(key))
            continue
        if 0<=slot<len(commands):
            command=commands[slot]
            replies.append({'request':slot,'value':typed(value)})
            if command[0]==b'GET':
                if value is None:cache.pop(command[1],None)
                elif isinstance(value,bytes):cache[command[1]]=value
        slot+=1
    return {
        'frames.json':[{'kind':f['kind'],'value':typed(f['value'])}for f in frames],
        'replies.json':{'reply_count':len(replies),'replies':replies,'invalidations':invalidations},
        'cache.json':{'entries':[[b64(k),b64(v)]for k,v in sorted(cache.items())]}}


def decode(raw,stride):
    decoder=task.Decoder();frames=[]
    for offset in range(0,len(raw),stride):frames.extend(decoder.feed(raw[offset:offset+stride]))
    if decoder.finish()!=[]:raise ValueError('EOF must produce no extra frames')
    return frames


def derive(directory,generation,prefix,stride):
    request=json.loads((directory/'request.json').read_text(encoding='utf-8'))
    if request['generation']!=generation or request['prefix']!=prefix:raise ValueError('request identity')
    raw=(directory/'wire.bin').read_bytes()
    if len(raw)>8388608:raise ValueError('wire budget')
    products=outputs(request,decode(raw,stride),prefix)
    manifest={'schema':1,'generation':generation,'prefix':prefix,'wire_sha256':hashlib.sha256(raw).hexdigest(),
              'request_sha256':digest(request),'artifacts':{name:digest(value)for name,value in products.items()}}
    return products,manifest


def main(argv=None):
    parser=argparse.ArgumentParser()
    parser.add_argument('phase',choices=['capture','replay','promote'])
    parser.add_argument('--socket');parser.add_argument('--request')
    parser.add_argument('--root',required=True);parser.add_argument('--generation',required=True)
    parser.add_argument('--prefix',required=True);parser.add_argument('--stride',type=int,default=7)
    args=parser.parse_args(argv)
    if not re.fullmatch(r'of:[a-f0-9]{16,48}:',args.prefix)or not re.fullmatch(r'[a-z0-9_-]{1,32}',args.generation):raise ValueError('dedicated prefix/generation')
    if not 1<=args.stride<=65536:raise ValueError('fragment size')
    directory=prepare_directory(args.root,args.generation)
    if args.phase=='capture':
        if (directory/'wire.bin').exists()or(directory/'wire.partial').exists():
            raise ValueError('capture generation already attempted; replay or use a new generation')
        value=json.loads(Path(args.request).read_text(encoding='utf-8'))
        stages=requests(value,args.prefix)
        request={'generation':args.generation,'prefix':args.prefix,'stages':value['stages']}
        write_new(directory/'request.json',request)
        decoder=task.Decoder();frames=[];raw=bytearray();normal_count=0
        sock=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);sock.settimeout(4)
        try:
            with (directory/'wire.partial').open('xb')as partial:
                sock.connect(args.socket)
                def receive(expected):
                    nonlocal normal_count
                    while normal_count<expected:
                        chunk=sock.recv(args.stride)
                        if not chunk:raise ValueError('truncated native session')
                        raw.extend(chunk);partial.write(chunk);partial.flush()
                        if len(raw)>8388608:raise ValueError('wire budget')
                        decoded=decoder.feed(chunk);frames.extend(decoded)
                        normal_count+=sum(f['kind']=='reply'for f in decoded)
                sock.sendall(wire([b'HELLO',b'3']));receive(1)
                sock.sendall(wire([b'CLIENT',b'TRACKING',b'ON',b'BCAST',b'PREFIX',args.prefix.encode()]));receive(2)
                expected=2
                for index,batch in enumerate(stages):
                    sock.sendall(b''.join(wire(parts)for parts in batch))
                    expected+=len(batch);receive(expected)
                    print(json.dumps({'phase':'stage','stage':index,'reply_count':expected-2}),flush=True)
                    if sys.stdin.readline()!='continue\n':raise ValueError('stage gate requires continue')
                sock.sendall(wire([b'CLIENT',b'TRACKING',b'OFF']));receive(expected+1)
                sock.shutdown(socket.SHUT_WR)
                while True:
                    chunk=sock.recv(args.stride)
                    if not chunk:break
                    raw.extend(chunk);partial.write(chunk)
                    if len(raw)>8388608:raise ValueError('wire budget')
                    frames.extend(decoder.feed(chunk))
                partial.flush();os.fsync(partial.fileno())
                if decoder.finish()!=[]:raise ValueError('incomplete final frame')
            outputs(request,frames,args.prefix)
            publish_bytes(directory/'wire.bin',bytes(raw))
            products,manifest=derive(directory,args.generation,args.prefix,args.stride)
            for name,product in products.items():write_new(directory/name,product)
            write_new(directory/'manifest.json',manifest)
            (directory/'wire.partial').unlink()
        except (ValueError,KeyError,TypeError,OSError)as error:
            write_new(directory/'failure.json',{'schema':1,'complete':False,'bytes_received':len(raw),'error':str(error)})
            raise
        finally:sock.close()
        print(json.dumps({'phase':'capture','complete':True,'wire_sha256':manifest['wire_sha256']}));return
    products,manifest=derive(directory,args.generation,args.prefix,args.stride)
    if args.phase=='replay':
        for name,product in products.items():write_new(directory/name,product)
        write_new(directory/'manifest.json',manifest)
        write_new(directory/'validated.json',{'schema':1,'generation':args.generation,'manifest_sha256':digest(manifest)})
        print(json.dumps({'phase':'replay','complete':True,'manifest_sha256':digest(manifest)}));return
    for name,product in products.items():
        if json.loads((directory/name).read_text(encoding='utf-8'))!=product:raise ValueError('derived artifact changed')
    if json.loads((directory/'manifest.json').read_text(encoding='utf-8'))!=manifest:raise ValueError('manifest changed')
    validated={'schema':1,'generation':args.generation,'manifest_sha256':digest(manifest)}
    if json.loads((directory/'validated.json').read_text(encoding='utf-8'))!=validated:raise ValueError('offline replay not validated')
    write_new(directory/'published.json',{'schema':1,'generation':args.generation,'manifest_sha256':digest(manifest),'committed':True})
    print(json.dumps({'phase':'promote','committed':True,'manifest_sha256':digest(manifest)}))


if __name__=='__main__':
    try:main()
    except (ValueError,KeyError,TypeError,OSError)as error:
        print(str(error),file=sys.stderr);raise SystemExit(2)

